    // Struct to define the range for an attribute, including quartiles.
    public struct AttributeRange
    {
        public int Min { get; set; }
        public int Max { get; set; }
        public int Q1 { get; set; } // First Quartile (25th percentile)
        public int Q3 { get; set; } // Third Quartile (75th percentile)
    }

    // Struct to hold an individual player attribute name and its range.
    public struct PlayerAttribute
    {
        public string Name { get; set; }
        public AttributeRange Range { get; set; }
    }
