        /// <summary>
        /// Generates a random attribute value within the specified range, biased by a quality score (0-100).
        /// A quality score of 70 maps to the midpoint of the attribute's range.
        /// </summary>
        /// <param name="range">The base attribute range (Min, Max, Q1, Q3).</param>
        /// <param name="qualityScore">A score from 0 (lowest quality) to 100 (highest quality) to bias attribute generation.</param>
        private static int GenerateAttributeValue(AttributeRange range, int qualityScore)
        {
            // Clamp qualityScore to be within 0-100.
            qualityScore = Math.Max(0, Math.Min(100, qualityScore));

            double normalizedQualityFactor;
            const int normalQualityMidpoint = 70; // Define 70 as the new "normal" quality score

            // Map the quality score to a normalized factor (0.0 to 1.0)
            if (qualityScore <= normalQualityMidpoint)
            {
                // Scale from 0 (Min) to 0.5 (Midpoint) as qualityScore goes from 0 to normalQualityMidpoint
                normalizedQualityFactor = (qualityScore / (double)normalQualityMidpoint) * 0.5;
            }
            else // qualityScore > normalQualityMidpoint
            {
                // Scale from 0.5 (Midpoint) to 1.0 (Max) as qualityScore goes from normalQualityMidpoint to 100
                normalizedQualityFactor = 0.5 + ((qualityScore - normalQualityMidpoint) / (double)(100 - normalQualityMidpoint)) * 0.5;
            }

            // Calculate a target value based on interpolation across the full Min-Max range using the new factor.
            double targetValue = range.Min + (range.Max - range.Min) * normalizedQualityFactor;

            // Introduce randomness around the target value.
            // A smaller deviation will result in more predictable attributes for a given qualityScore.
            // A larger deviation will make attributes more varied.
            double deviationPercentage = 0.20; // Example: +/- 20% of the attribute's total range
            double deviationAmount = (range.Max - range.Min) * deviationPercentage;

            // Generate a random offset between -deviationAmount and +deviationAmount.
            double randomOffset = (random.NextDouble() * 2 - 1) * deviationAmount;

            // Calculate the raw attribute value by adding the random offset to the target value.
            double rawValue = targetValue + randomOffset;

            // Clamp the raw value to ensure it stays strictly within the attribute's defined Min and Max range.
            int finalValue = (int)Math.Round(Math.Max(range.Min, Math.Min(range.Max, rawValue)));

            return finalValue;
        }

        /// <summary>
        /// Generates a new player with attributes based on position, age, and a specified quality score.
        /// </summary>
        /// <param name="name">The name of the player.</param>
        /// <param name="age">The age of the player (16-41+).</param>
        /// <param name="position">The position of the player (e.g., "ST").</param>
        /// <param name="qualityScore">The desired quality of the player (0-100, where 0 is poor, 100 is elite).</param>
        /// <returns>A new Player struct with generated attributes.</returns>
        public static void GeneratePlayerWithQuality(Player p, int qualityScore)
        {
            int age = p.age;
            if (qualityScore < 80)
                qualityScore -= 8;

            // Determine age group based on the player's age.
            string ageGroup;
            if (age >= 16 && age <= 20) ageGroup = "16-20";
            else if (age >= 21 && age <= 23) ageGroup = "21-23";
            else if (age >= 24 && age <= 26) ageGroup = "24-26";
            else if (age >= 27 && age <= 29) ageGroup = "27-29";
            else if (age >= 30 && age <= 32) ageGroup = "30-32";
            else if (age >= 33 && age <= 35) ageGroup = "33-35";
            else if (age >= 36 && age <= 40) ageGroup = "36-40";
            else if (age >= 41) ageGroup = "41+";
            else throw new ArgumentOutOfRangeException("Age must be between 16 and 41+.");

            string position = Enums.ConvertPositionToString(p.PreferredPosition);

            // Check if the specified position exists in the data.
            if (!PositionAgeAttributeData.ContainsKey(position))
            {
                throw new ArgumentException("Position " + position + " not found in data.");
            }

            // Check if the age group is defined for the given position.
            if (!PositionAgeAttributeData[position].ContainsKey(ageGroup))
            {
                throw new ArgumentException("Age group " + ageGroup + " not found for position '{position}'.");
            }

            var attributes = new Dictionary<string, int>();
            // Iterate through each attribute defined for the position and age group.
            foreach (var attr in PositionAgeAttributeData[position][ageGroup])
            {
                // Generate the attribute value using the quality score.
                attributes[attr.Name] = GenerateAttributeValue(attr.Range, qualityScore);
            }

            p.trueRating.pace = attributes["Pace"];
            p.trueRating.shooting = attributes["Shooting"];
            p.trueRating.passing = attributes["Passing"];
            p.trueRating.defending = attributes["Defense"];
            p.trueRating.physicality = attributes["Physicality"];
            p.trueRating.acceleration = attributes["Acceleration"];
            p.trueRating.sprint = attributes["SprintSpeed"];
            p.trueRating.positioning = attributes["Positioning"];
            p.trueRating.finishing = attributes["Finishing"];
            p.trueRating.shotPower = attributes["ShotPower"];
            p.trueRating.longShot = attributes["LongShots"];
            p.trueRating.volleys = attributes["Volleys"];
            p.trueRating.penalties = attributes["Penalties"];
            p.trueRating.vision = attributes["Vision"];
            p.trueRating.crossing = attributes["Crossing"];
            p.trueRating.freekicks = attributes["FreeKickAccuracy"];
            p.trueRating.shortPass = attributes["ShortPassing"];
            p.trueRating.longPass = attributes["LongPassing"];
            p.trueRating.curve = attributes["Curve"];
            p.trueRating.dribbling = attributes["Dribbling"];
            p.trueRating.agility = attributes["Agility"];
            p.trueRating.balance = attributes["Balance"];
            p.trueRating.reactionTime = attributes["Reactions"];
            p.trueRating.ballControl = attributes["BallControl"];
            p.trueRating.composure = attributes["Composure"];
            p.trueRating.intercept = attributes["Interceptions"];
            p.trueRating.header = attributes["HeadingAccuracy"];
            p.trueRating.defenseAwareness = attributes["DefAwareness"];
            p.trueRating.standTackle = attributes["StandingTackle"];
            p.trueRating.slideTackle = attributes["SlidingTackle"];
            p.trueRating.jumping = attributes["Jumping"];
            p.trueRating.stamina = attributes["Stamina"];
            p.trueRating.strength = attributes["Strength"];
            p.trueRating.aggression = attributes["Aggression"];

            if (p.PreferredPosition == Enums.Positions.Goalkeeper)
            {
                p.trueRating.goalkeepingDiving = attributes["GK Diving"];
                 p.trueRating.GoalKeepingHandling = attributes["GK Handling"];
                 p.trueRating.goalKeepingKicking = attributes["GK Kicking"];
                 p.trueRating.GoalKeepingPositioning = attributes["GK Positioning"];
                 p.trueRating.goalKeepingReflexes = attributes["GK Reflexes"];
            }
        }

        /// <summary>
        /// Calculates the overall rating for a player based on their position and attributes.
        /// Weights are adjusted for Striker (ST) specific attributes.
        /// </summary>
        private static int CalculateOverallRating(string position, Dictionary<string, int> attributes)
        {
            double overall = 0;
            switch (position)
            {
                case "ST":
                    // Key attributes for a Striker (ST)
                    overall = (
                        attributes["Finishing"] * 0.20 +
                        attributes["Positioning"] * 0.15 +
                        attributes["ShotPower"] * 0.10 +
                        attributes["Pace"] * 0.10 +
                        attributes["Dribbling"] * 0.10 +
                        attributes["BallControl"] * 0.10 +
                        attributes["Reactions"] * 0.05 +
                        attributes["Volleys"] * 0.05 +
                        attributes["Jumping"] * 0.05 +
                        attributes["Strength"] * 0.05
                    );
                    break;
                // Add other positions here when their data is available
                default:
                    // Fallback for unconfigured positions - simple average
                    if (attributes.Any())
                    {
                        overall = attributes.Values.Average();
                    }
                    break;
            }
            return (int)Math.Round(overall);
        }
    }
